		private static void clearEgg(global::Pml.PokeParty party) {
			uint idx = 0;
			while (idx < party.GetMemberCount())
			{
				if (party.GetMemberPointerConst(idx).IsEgg(Pml.PokePara.EggCheckType.BOTH_EGG))
					party.RemoveMember(idx);
				else
					idx++;
			}
		}
		private static void player_balldeco(global::Dpr.Battle.Logic.BATTLE_SETUP_PARAM dst, global::Pml.PokeParty party) {
			Dpr.BallDeco.BallDecoWork.ClearTempAttachCapsuleFlags();
			Dpr.BallDeco.CapsuleData[] capsuleDatas = dst.ballDecoDesc[(int)BTL_CLIENT_ID.BTL_CLIENT_PLAYER];
			for (uint i = 0; i < party.GetMemberCount(); i++)
			{
				Pml.PokePara.PokemonParam pp = party.GetMemberPointerConst(i);
				if (pp != null && !pp.IsNull())
				{
					int capsuleId = Dpr.BallDeco.BallDecoWork.GetAttachCapsuleId(pp.GetID(), pp.GetPersonalRnd(), -1, (int)i);
					if (capsuleId >= 0)
					{
						capsuleDatas[i] = Dpr.BallDeco.BallDecoWork.GetCapsuleData(capsuleId);
						Dpr.BallDeco.BallDecoWork.SetTempAttachCapsuleFlag((int)i, true);
						continue;
					}
				}
				capsuleDatas[i].Clear();
				Dpr.BallDeco.BallDecoWork.SetTempAttachCapsuleFlag((int)i, false);
			}
		}
