					if (i < sealTIDs.Length)
						sealTemplateID = sealTIDs[i];
					Pml.PokePara.PokemonParam pp = trainerParty.GetMemberPointer(i);
					TrainerSystem.SetupSealTemplate(ref capsuleDatas[i], sealTemplateID, pp);
				}
			}
		}
		public static void settingByTrainerData(global::Dpr.Battle.Logic.BATTLE_SETUP_PARAM bp, in global::Dpr.Battle.Logic.BSP_TRAINER_DATA trData) {
			if (trData != null)
			{
				BattleSetupEffectId setupEffectId = trData.GetBattleEffectID();
				if (setupEffectId != BattleSetupEffectId.NONE)
					bp.btlEffComponent.SetUpBattleEffectComponentData(setupEffectId, EffectBattleID.NONE, 0, null);
			}
		}
		static Setup() { }
	}
}
